<div class="builder-left"><div class="builder-heading">Triggers</div><div class="nodeitem" data-type="trigger" data-title="Order created" onclick="addWorkflowNode('trigger','Order created','◉','purple',{topic:'ORDERS_CREATE'})"><span class="node-symbol">◉</span>Order created</div><div class="nodeitem" data-type="trigger" onclick="addWorkflowNode('trigger','Checkout inactivity (recovery)','◷','purple',{topic:'CHECKOUTS_CREATE'})"><span class="node-symbol">◷</span>Checkout inactivity (recovery)</div><div class="nodeitem" data-type="trigger" onclick="addWorkflowNode('trigger','Fulfillment created','♧','green',{topic:'FULFILLMENTS_CREATE'})"><span class="node-symbol green">♧</span>Fulfillment created</div><hr class="divider"><div class="builder-heading">Conditions & timing</div><div class="nodeitem" onclick="addWorkflowNode('condition','Condition','⑂','orange',{field:'payment_gateway_names',operator:'contains',value:'cash on delivery'})"><span class="node-symbol orange">⑂</span>Condition / split</div><div class="nodeitem" onclick="addWorkflowNode('delay','Time delay','◷','blue',{minutes:60})"><span class="node-symbol blue">◷</span>Time delay</div><div class="nodeitem" onclick="addWorkflowNode('wait_for_reply','Wait for reply','◷','blue',{timeout_minutes:120,yes_words:['yes','confirm'],no_words:['no','cancel']})"><span class="node-symbol blue">◷</span>Wait for reply</div><hr class="divider"><div class="builder-heading">WhatsApp</div><div class="nodeitem" onclick="addWorkflowNode('send_template','Send WhatsApp template','◉','green',{template_name:'',message_purpose:'order_update',phone:'@{{order.customer.phone}}',body_params:['@{{order.customer.first_name}}','@{{order.name}}']})"><span class="node-symbol green">◉</span>Send template</div><hr class="divider"><div class="builder-heading">Shopify & actions</div><div class="nodeitem" onclick="addWorkflowNode('add_order_tag','Add order tag','＋','green',{tag:'whatify_cod_confirmed'})"><span class="node-symbol green">＋</span>Add order tag</div><div class="nodeitem" onclick="addWorkflowNode('notify_staff','Notify staff','♧','blue',{message:'Order needs manual review'})"><span class="node-symbol blue">♧</span>Notify staff</div><div class="nodeitem" onclick="addWorkflowNode('cancel_order','Cancel order','×','red',{})"><span class="node-symbol red">×</span>Cancel order</div><div class="nodeitem" onclick="addWorkflowNode('stop','Stop workflow','■','red',{})"><span class="node-symbol red">■</span>Stop workflow</div><div class="confighint" style="margin:14px 6px">Drag nodes to arrange. Select a node, choose an output, then connect it to another step.</div></div>
