@push('scripts')
<script>
const workflowId=@json($workflow->id), updateUrl=@json(route('automations.update',$workflow)), csrf=document.querySelector('meta[name="csrf-token"]').content, approvedTemplates=@json($templates);
let graph=@json($graph), selectedId=null, connectFrom=null, outputHandle='', zoomScale=1, dirty=false;
if(!graph||!Array.isArray(graph.nodes))graph={nodes:[],edges:[]};if(!Array.isArray(graph.edges))graph.edges=[];
function nodeById(id){return graph.nodes.find(n=>n.id===id)}function setDirty(){dirty=true;document.getElementById('saveStatus').textContent='Unsaved changes';document.getElementById('saveStatus').style.color='#b77b20'}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderGraph(){const canvas=document.getElementById('workflowCanvas');canvas.querySelectorAll('.nodebox,.plusnode,.branch-label').forEach(e=>e.remove());const svg=document.getElementById('workflowEdges');svg.innerHTML='';let maxY=700;graph.nodes.forEach(n=>maxY=Math.max(maxY,(n.y||30)+125));canvas.style.height=(maxY+100)+'px';svg.setAttribute('viewBox',`0 0 960 ${maxY+100}`);graph.edges.forEach((e,i)=>{const a=nodeById(e.source),b=nodeById(e.target);if(!a||!b)return;const x1=(a.x||360)+105,y1=(a.y||30)+88,x2=(b.x||360)+105,y2=(b.y||30);let mid=Math.max(y1+25,(y1+y2)/2);const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M ${x1} ${y1} V ${mid} H ${x2} V ${y2}`);path.setAttribute('fill','none');path.setAttribute('stroke','#c5c1cf');path.setAttribute('stroke-width','1.6');svg.appendChild(path);const label=e.sourceHandle;if(label){const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('x',(x1+x2)/2+5);t.setAttribute('y',mid-5);t.setAttribute('font-size','10');t.setAttribute('fill',label==='true'||label==='yes'?'#299563':'#bc6866');t.textContent=label;svg.appendChild(t)}});
graph.nodes.forEach(n=>{const d=document.createElement('div');d.dataset.id=n.id;d.className='nodebox'+(selectedId===n.id?' selected':'')+(connectFrom===n.id?' connection-mode':'');d.style.left=(n.x??360)+'px';d.style.top=(n.y??30)+'px';let color=({send_template:'green',add_order_tag:'green',condition:'orange',delay:'blue',wait_for_reply:'blue',notify_staff:'blue',cancel_order:'red',stop:'red',trigger:'purple'})[n.type]||'purple';let icon=({trigger:'◉',condition:'⑂',send_template:'◉',wait_for_reply:'◷',delay:'◷',add_order_tag:'＋',notify_staff:'♧',cancel_order:'×',stop:'■'})[n.type]||'↗';d.innerHTML=`<div class="nbhead drag-handle"><span class="nbicon ${color}">${icon}</span><div><div class="nbtitle">${esc(n.title||n.type)}</div><div class="nbsub">${esc(n.type.replaceAll('_',' '))}</div></div><button class="closeconfig" style="margin-left:auto;font-size:15px" title="Remove step">×</button></div><div class="nbdetail">${esc(nodeSummary(n))}</div>`;d.addEventListener('click',e=>{if(e.target.tagName==='BUTTON'){e.stopPropagation();removeNode(n.id);return}if(connectFrom&&connectFrom!==n.id){connectNodes(connectFrom,n.id,outputHandle);connectFrom=null;outputHandle='';return}selectNode(n.id)});makeDraggable(d,n);canvas.appendChild(d)});canvas.style.transform=`scale(${zoomScale})`;canvas.style.transformOrigin='top center';if(selectedId)renderConfig();}
function nodeSummary(n){let c=n.config||{};return ({trigger:c.topic||'Select an event',condition:`${c.field||'field'} ${c.operator||'equals'} ${c.value||''}`,send_template:c.template_name||'Choose an approved template',wait_for_reply:`Timeout: ${c.timeout_minutes||120} min`,delay:`Wait ${c.minutes||5} minutes`,add_order_tag:`Tag: ${c.tag||'enter tag'}`,notify_staff:c.message||'Staff notification',cancel_order:'Disabled by default safety policy',stop:'End this workflow'})[n.type]||'Configure this step'}
function selectNode(id){selectedId=id;renderGraph();renderConfig()}
function clearSelection(){selectedId=null;connectFrom=null;document.getElementById('nodeConfig').innerHTML='<div class="empty-state">Select a step on the canvas to configure it.</div>';renderGraph()}
function addWorkflowNode(type,title,icon,color,config){const id='node-'+Math.random().toString(36).slice(2,10);const maxY=graph.nodes.reduce((m,n)=>Math.max(m,n.y||0),0);const n={id,type,title,x:360,y:graph.nodes.length?maxY+145:35,config:structuredClone(config||{})};graph.nodes.push(n);if(selectedId)graph.edges.push({source:selectedId,target:id,sourceHandle:sourceDefault(selectedId)});selectedId=id;setDirty();renderGraph();renderConfig()}
function sourceDefault(id){const n=nodeById(id);if(n?.type==='condition')return 'true';if(n?.type==='wait_for_reply')return 'yes';return undefined}
function connectNodes(from,to,handle){if(from===to)return;graph.edges=graph.edges.filter(e=>!(e.source===from&&((e.sourceHandle||'')===(handle||''))));graph.edges.push({source:from,target:to,...(handle?{sourceHandle:handle}:{})});setDirty();renderGraph();document.getElementById('canvasHint').textContent='Steps connected';}
function removeNode(id){graph.nodes=graph.nodes.filter(n=>n.id!==id);graph.edges=graph.edges.filter(e=>e.source!==id&&e.target!==id);if(selectedId===id)selectedId=null;setDirty();renderGraph();renderConfig()}
function makeDraggable(el,n){let start=null;el.addEventListener('pointerdown',e=>{if(!e.target.closest('.drag-handle')||e.target.tagName==='BUTTON')return;start={x:e.clientX,y:e.clientY,left:n.x||0,top:n.y||0};el.setPointerCapture(e.pointerId);el.classList.add('dragging')});el.addEventListener('pointermove',e=>{if(!start)return;const rect=el.parentElement.getBoundingClientRect();n.x=Math.max(0,Math.round(start.left+(e.clientX-start.x)/zoomScale));n.y=Math.max(0,Math.round(start.top+(e.clientY-start.y)/zoomScale));el.style.left=n.x+'px';el.style.top=n.y+'px'});el.addEventListener('pointerup',()=>{if(start){start=null;el.classList.remove('dragging');setDirty();renderGraph()}})}
function configInput(key,label,value,type='text',placeholder=''){const val=Array.isArray(value)?value.join(', '):(value??'');return `<label class="configlabel">${esc(label)}</label>${type==='textarea'?`<textarea class="field textarea" data-key="${esc(key)}" placeholder="${esc(placeholder)}">${esc(val)}</textarea>`:`<input class="field" data-key="${esc(key)}" type="${type}" value="${esc(val)}" placeholder="${esc(placeholder)}">`}`}
function renderConfig(){const n=nodeById(selectedId);if(!n){document.getElementById('nodeConfig').innerHTML='<div class="empty-state">Select a step on the canvas to configure it.</div>';return}const c=n.config||(n.config={});let html=`<div class="confighead"><span class="node-symbol">↗</span><div><strong>${esc(n.title)}</strong><small>${esc(n.type.replaceAll('_',' '))}</small></div></div>${configInput('title','Step name',n.title)}`;
if(n.type==='trigger')html+=`<label class="configlabel">Shopify event</label><select class="field" data-key="topic"><option value="ORDERS_CREATE" ${c.topic==='ORDERS_CREATE'?'selected':''}>Order created</option><option value="FULFILLMENTS_CREATE" ${c.topic==='FULFILLMENTS_CREATE'?'selected':''}>Fulfillment created</option><option value="CHECKOUTS_CREATE" ${c.topic==='CHECKOUTS_CREATE'?'selected':''}>Checkout inactivity (recovery)</option></select>${c.topic==='CHECKOUTS_CREATE'?'<div class="confighint">Uses Shopify checkout create/update events, waits for inactivity, suppresses completed checkouts, and requires cart-recovery marketing opt-in.</div>':''}`;
if(n.type==='condition')html+=configInput('field','Order field',c.field||'payment_gateway_names')+`<label class="configlabel">Operator</label><select class="field" data-key="operator">${['contains','equals','not_equals','greater_than','less_than','not_contains'].map(x=>`<option ${c.operator===x?'selected':''}>${x}</option>`).join('')}</select>`+configInput('value','Compare value',c.value||'cash on delivery');
if(n.type==='send_template')html+=`<label class="configlabel">Approved Whatify template</label><input class="field" list="approved-template-list" data-key="template_name" value="${esc(c.template_name||'')}" placeholder="Select or type approved name"><datalist id="approved-template-list">${approvedTemplates.map(t=>`<option value="${esc(t.name)}">${esc(t.category||'utility')} · ${esc(t.language||'')}</option>`).join('')}</datalist><label class="configlabel">Message purpose / consent type</label><select class="field" data-key="message_purpose"><option value="order_update" ${(c.message_purpose||'order_update')==='order_update'?'selected':''}>Transactional / order updates</option><option value="marketing" ${c.message_purpose==='marketing'?'selected':''}>Marketing / cart recovery</option></select>`+configInput('phone','Customer phone',c.phone||(c.message_purpose==='marketing'?'@{{checkout.customer.phone}}':'@{{order.customer.phone}}'))+configInput('body_params','Body parameters (comma-separated)',(c.body_params||[]).join(', '),'textarea',c.message_purpose==='marketing'?'@{{checkout.customer.first_name}}, @{{checkout.item_summary}}, @{{checkout.shop_name}}, @{{checkout.abandoned_checkout_url}}':'@{{order.customer.first_name}}, @{{order.name}}')+`<div class="confighint">Placeholder order must exactly match the approved Whatify template. Marketing sends require a separate active cart-recovery opt-in; order-update consent is not reused.</div>`;
if(n.type==='wait_for_reply')html+=configInput('timeout_minutes','Timeout minutes',c.timeout_minutes||120,'number')+configInput('yes_words','Confirmation keywords',c.yes_words||['yes','confirm'])+configInput('no_words','Cancel / decline keywords',c.no_words||['no','cancel']);
if(n.type==='delay')html+=configInput('minutes','Delay minutes',c.minutes||5,'number');if(n.type==='add_order_tag')html+=configInput('tag','Shopify order tag',c.tag||'whatify_cod_confirmed');if(n.type==='notify_staff')html+=configInput('message','Staff notification text',c.message||'Order needs manual review','textarea');
html+=`<label class="configlabel">Connect output to</label><select class="field" id="outputHandle"><option value="">Default / continue</option>${n.type==='condition'?'<option value="true">Condition true</option><option value="false">Condition false</option>':''}${n.type==='wait_for_reply'?'<option value="yes">Customer confirmed</option><option value="no">Customer declined</option><option value="timeout">No reply / timeout</option>':''}</select><button class="secondary full" style="margin-top:8px" onclick="armConnection()">＋ &nbsp;Connect to another step</button><div class="confighint">After clicking, choose the destination block on the canvas.</div><button class="secondary full" style="margin-top:17px;color:#c65d5d" onclick="removeNode('${esc(n.id)}')">Remove step</button>`;
document.getElementById('nodeConfig').innerHTML=html;document.querySelectorAll('#nodeConfig [data-key]').forEach(input=>input.addEventListener('input',()=>{const key=input.dataset.key,val=input.value;if(key==='title'){n.title=val;const card=document.querySelector(`.nodebox[data-id="${CSS.escape(n.id)}"] .nbtitle`);if(card)card.textContent=val;setDirty();return}if(key==='body_params')c[key]=val.split(',').map(x=>x.trim()).filter(Boolean);else if(['yes_words','no_words'].includes(key))c[key]=val.split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);else if(key==='timeout_minutes'||key==='minutes')c[key]=Math.max(1,parseInt(val||'1'));else c[key]=val;if(key==='message_purpose'){c.phone=val==='marketing'?'@{{checkout.customer.phone}}':'@{{order.customer.phone}}';c.body_params=val==='marketing'?['@{{checkout.customer.first_name}}','@{{checkout.item_summary}}','@{{checkout.shop_name}}','@{{checkout.abandoned_checkout_url}}']:['@{{order.customer.first_name}}','@{{order.name}}'];setDirty();renderGraph();renderConfig();return}setDirty();const summary=document.querySelector(`.nodebox[data-id="${CSS.escape(n.id)}"] .nbdetail`);if(summary)summary.textContent=nodeSummary(n)}));}
function armConnection(){connectFrom=selectedId;outputHandle=document.getElementById('outputHandle').value;document.getElementById('canvasHint').textContent='Choose a destination node';renderGraph()}
function setZoom(n){zoomScale=Math.max(.6,Math.min(1.2,zoomScale+n));renderGraph()}function centerCanvas(){document.querySelector('.canvas').scrollTo({left:0,top:0,behavior:'smooth'})}
function autoArrange(){graph.nodes.forEach((n,i)=>{n.x=360;n.y=30+i*145});setDirty();renderGraph()}
async function saveGraph(){const status=document.getElementById('saveStatus');status.textContent='Saving…';try{const response=await fetch(updateUrl,{method:'PUT',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({name:document.getElementById('workflowName').value,description:document.getElementById('workflowDescription').value,graph})});const data=await response.json();if(!response.ok)throw new Error(data.message||Object.values(data.errors||{}).flat()[0]||'Save failed');dirty=false;status.textContent='Saved just now';status.style.color='#278653';return true}catch(e){status.textContent='Save failed';status.style.color='#bf6664';alert(e.message);return false}}
async function publishGraph(){if(!graph.nodes.some(n=>n.type==='trigger'))return alert('Add a Shopify trigger before publishing.');if(await saveGraph())document.getElementById('publishForm').submit()}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});renderGraph();if(graph.nodes[0])selectNode(graph.nodes[0].id);
</script>
@endpush
